function solve(a, b) {
  const out = [];
  let i = 0, j = 0, carry = 0;
  while (i < a.length || j < b.length || carry) {
    const x = i < a.length ? a[i++] : 0;
    const y = j < b.length ? b[j++] : 0;
    const sum = x + y + carry;
    out.push(sum % 10);
    carry = Math.floor(sum / 10);
  }
  return out;
}
